export interface AttendanceState {
  totalClasses: number;
  absentClasses: number;
  examDate: string; // YYYY-MM-DD
  holidays: string[]; // Array of YYYY-MM-DD
  extraWorkingDays: string[]; // Array of YYYY-MM-DD (Weekends marked as working)
}

export interface AttendanceStats {
  currentPercentage: number;
  isSafe: boolean; // > 75%
  classesUntilExam: number; // Total slots
  bunkableClasses: number; // How many can be skipped safely
  bunkableDays: number; // Number of full days that can be skipped
  requiredClasses: number; // How many consecutive must be attended if unsafe
  requiredDays: number; // Number of full days to attend to reach safety
  tomorrowImpact: number; // Percentage if absent tomorrow
  isPossibleToReachTarget: boolean; // Whether 75% is reachable before exam
  maxAchievablePercentage: number; // Max % if attending every class from now on
  hasExamDate: boolean; // Whether a valid future exam date is provided
}

import { AttendanceState, AttendanceStats } from '../types';

const DAILY_CLASSES = 6;
const TARGET_PERCENTAGE = 75;

export const isWeekend = (date: Date): boolean => {
  const day = date.getDay();
  return day === 0 || day === 6; // Sunday = 0, Saturday = 6
};

export const getWorkingDaysBetween = (start: Date, end: Date, holidays: string[], extraWorkingDays: string[] = []): number => {
  let count = 0;
  const current = new Date(start);

  // Normalize to start of day
  current.setHours(0, 0, 0, 0);
  const endDate = new Date(end);
  endDate.setHours(0, 0, 0, 0);

  // Avoid infinite loops if dates are wrong
  if (current >= endDate) return 0;

  while (current < endDate) {
    const dateString = current.toISOString().split('T')[0];
    const isWknd = isWeekend(current);

    // A day is working if:
    // 1. It is a weekday AND NOT in holidays
    // 2. OR It is a weekend AND IS in extraWorkingDays
    const isWorkingDay = (!isWknd && !holidays.includes(dateString)) || (isWknd && extraWorkingDays.includes(dateString));

    if (isWorkingDay) {
      count++;
    }
    current.setDate(current.getDate() + 1);
  }
  return count;
};

export const calculateStats = (state: AttendanceState): AttendanceStats => {
  const { totalClasses, absentClasses, examDate, holidays, extraWorkingDays = [] } = state;

  // Derive attended classes
  const attendedClasses = Math.max(0, totalClasses - absentClasses);

  // 1. Current Percentage
  const currentPercentage = totalClasses === 0 ? 0 : (attendedClasses / totalClasses) * 100;

  // 2. Classes until exam
  const today = new Date();
  const exam = new Date(examDate);
  // If exam date is invalid or in past, assume 0 future days
  const validExamDate = examDate !== '' && !isNaN(exam.getTime()) && exam > today;

  const workingDaysLeft = validExamDate ? getWorkingDaysBetween(today, exam, holidays, extraWorkingDays) : 0;
  const classesUntilExam = workingDaysLeft * DAILY_CLASSES;

  // 3. Max Achievable logic
  const maxPossibleAttended = attendedClasses + classesUntilExam;
  const maxPossibleTotal = totalClasses + classesUntilExam;
  const maxAchievablePercentage = maxPossibleTotal === 0 ? 0 : (maxPossibleAttended / maxPossibleTotal) * 100;
  const isPossibleToReachTarget = maxAchievablePercentage >= TARGET_PERCENTAGE;

  // 4. Bunkable Classes logic
  const minRequiredTotalAttended = Math.ceil((TARGET_PERCENTAGE / 100) * maxPossibleTotal);
  const minFutureAttended = Math.max(0, minRequiredTotalAttended - attendedClasses);

  let bunkableClasses = classesUntilExam - minFutureAttended;
  if (bunkableClasses < 0) bunkableClasses = 0;
  const bunkableDays = Math.floor(bunkableClasses / DAILY_CLASSES);

  // 5. Required to recover (if currently unsafe)
  let requiredClasses = 0;
  if (currentPercentage < TARGET_PERCENTAGE && totalClasses > 0) {
     const needed = (0.75 * totalClasses - attendedClasses) / 0.25;
     requiredClasses = Math.ceil(needed);
  }
  const requiredDays = Math.ceil(requiredClasses / DAILY_CLASSES);

  // 6. Tomorrow Impact
  const tomorrowTotal = totalClasses + DAILY_CLASSES;
  const tomorrowPercentage = (attendedClasses / tomorrowTotal) * 100;

  return {
    currentPercentage,
    isSafe: currentPercentage >= TARGET_PERCENTAGE,
    classesUntilExam,
    bunkableClasses,
    bunkableDays,
    requiredClasses,
    requiredDays,
    tomorrowImpact: tomorrowPercentage,
    isPossibleToReachTarget,
    maxAchievablePercentage,
    hasExamDate: validExamDate
  };
};

import React, { useState } from 'react';
import { motion } from 'framer-motion';

interface CalendarProps {
  holidays: string[];
  extraWorkingDays: string[];
  onDateToggle: (date: string, isWeekend: boolean) => void;
}

export const Calendar: React.FC<CalendarProps> = ({ holidays, extraWorkingDays, onDateToggle }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const getDaysInMonth = (year: number, month: number) => {
    return new Date(year, month + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (year: number, month: number) => {
    return new Date(year, month, 1).getDay();
  };

  const formatDate = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const daysInMonth = getDaysInMonth(year, month);
  const firstDay = getFirstDayOfMonth(year, month);

  const days = [];
  // Empty slots for prev month
  for (let i = 0; i < firstDay; i++) {
    days.push(null);
  }
  // Days
  for (let i = 1; i <= daysInMonth; i++) {
    days.push(new Date(year, month, i));
  }

  const handlePrevMonth = () => {
    setCurrentDate(new Date(year, month - 1, 1));
  };

  const handleNextMonth = () => {
    setCurrentDate(new Date(year, month + 1, 1));
  };

  const isWeekend = (date: Date) => {
    const day = date.getDay();
    return day === 0 || day === 6;
  };

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() && 
           date.getMonth() === today.getMonth() && 
           date.getFullYear() === today.getFullYear();
  };

  return (
    <div className="w-full select-none max-w-sm mx-auto">
      <div className="flex justify-between items-center mb-4">
        <button 
            onClick={handlePrevMonth} 
            className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white transition-colors active:scale-95"
        >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" />
            </svg>
        </button>
        <h3 className="text-white font-bold text-base font-mono">
            {currentDate.toLocaleDateString('default', { month: 'long', year: 'numeric' })}
        </h3>
        <button 
            onClick={handleNextMonth} 
            className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white transition-colors active:scale-95"
        >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
            </svg>
        </button>
      </div>

      <div className="grid grid-cols-7 gap-1 mb-2">
        {['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].map(day => (
            <div key={day} className="text-center text-[10px] text-slate-500 uppercase font-bold py-1">
                {day}
            </div>
        ))}
      </div>

      <div className="grid grid-cols-7 gap-1">
        {days.map((date, index) => {
            if (!date) return <div key={`empty-${index}`} />;

            const weekend = isWeekend(date);
            const dateStr = formatDate(date);
            const today = isToday(date);

            // A day is visually "selected" (Cyan/Holiday) if it is a day OFF.
            // 1. Weekend: OFF by default, unless in extraWorkingDays
            // 2. Weekday: ON by default, unless in holidays
            const isOff = weekend ? !extraWorkingDays.includes(dateStr) : holidays.includes(dateStr);

            return (
                <motion.button
                    key={dateStr}
                    whileTap={{ scale: 0.9 }}
                    onClick={() => onDateToggle(dateStr, weekend)}
                    className={`
                        aspect-square rounded-md flex flex-col items-center justify-center text-xs relative transition-colors duration-200 touch-manipulation
                        ${isOff ? 'bg-cyan-600/80 text-white shadow-[0_0_10px_rgba(8,145,178,0.4)]' : 
                          'bg-slate-800/40 text-slate-400 hover:bg-slate-700 hover:text-slate-200'}
                        ${today ? 'ring-1 ring-cyan-500/50' : ''}
                    `}
                >
                    <span className="relative z-10">{date.getDate()}</span>
                    {isOff && (
                        <motion.div 
                            layoutId={`selected-${dateStr}`} // Unique layout ID prevents cross-animation issues
                            className="absolute inset-0 border border-cyan-400/50 rounded-md" 
                            initial={false}
                        />
                    )}
                    {today && !isOff && (
                         <div className="absolute bottom-1 w-1 h-1 bg-cyan-400 rounded-full" />
                    )}
                </motion.button>
            );
        })}
      </div>

      <div className="mt-4 flex flex-col sm:flex-row gap-2 text-[10px] text-slate-500 justify-center">
        <div className="flex items-center gap-2 bg-slate-800/50 p-2 rounded-lg justify-center">
            <div className="w-2.5 h-2.5 bg-cyan-600/80 rounded shadow-[0_0_5px_rgba(8,145,178,0.5)] flex-shrink-0"></div>
            <span>Holiday / Off Day</span>
        </div>
        <div className="flex items-center gap-2 bg-slate-800/50 p-2 rounded-lg justify-center">
            <div className="w-2.5 h-2.5 bg-slate-800/40 border border-slate-700 rounded flex-shrink-0"></div>
            <span>Working Class Day</span>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence, useSpring } from 'framer-motion';
import { AttendanceState, AttendanceStats } from '../types';
import { calculateStats } from '../utils/calculations';
import { Modal } from './Modal';
import { Calendar } from './Calendar';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

// Helper component for smooth number transitions
const AnimatedCounter: React.FC<{ value: number; className?: string; toFixed?: number }> = ({ value, className, toFixed = 0 }) => {
  const ref = useRef<HTMLSpanElement>(null);
  const springValue = useSpring(value, { stiffness: 60, damping: 20 });

  useEffect(() => {
    springValue.set(value);
  }, [value, springValue]);

  useEffect(() => {
    return springValue.on("change", (latest) => {
      if (ref.current) {
        ref.current.textContent = latest.toFixed(toFixed);
      }
    });
  }, [springValue, toFixed]);

  return <span ref={ref} className={className}>{value.toFixed(toFixed)}</span>;
};

export const Dashboard: React.FC = () => {
  const [state, setState] = useState<AttendanceState>({
    totalClasses: 0,
    absentClasses: 0,
    examDate: '',
    holidays: [],
    extraWorkingDays: []
  });

  const [stats, setStats] = useState<AttendanceStats | null>(null);
  const [isHolidayModalOpen, setIsHolidayModalOpen] = useState(false);
  const [inputMode, setInputMode] = useState<'absent' | 'present'>('absent');

  useEffect(() => {
    setStats(calculateStats(state));
  }, [state]);

  const handleChange = (field: keyof AttendanceState, value: any) => {
    setState(prev => {
        const newState = { ...prev, [field]: value };

        if (field === 'totalClasses') {
            const newTotal = Math.max(0, Number(value));
            newState.totalClasses = newTotal;
            // Absent cannot be more than total
            if (newState.absentClasses > newTotal) {
                newState.absentClasses = newTotal;
            }
        } else if (field === 'absentClasses') {
            const newAbsent = Math.max(0, Number(value));
            // Absent cannot be more than total
            if (newAbsent > newState.totalClasses) {
                newState.absentClasses = newState.totalClasses;
            } else {
                newState.absentClasses = newAbsent;
            }
        }

        return newState;
    });
  };

  const handleAttendanceChange = (val: number) => {
    if (inputMode === 'absent') {
      handleChange('absentClasses', val);
    } else {
      // User is inputting "Present" classes
      const currentTotal = state.totalClasses;
      const validPresent = Math.min(Math.max(0, val), currentTotal);
      const newAbsent = currentTotal - validPresent;
      handleChange('absentClasses', newAbsent);
    }
  };

  const toggleHoliday = (date: string, isWeekend: boolean) => {
    setState(prev => {
        if (isWeekend) {
            // Logic for Weekends:
            // Default: OFF (Holiday).
            // If user toggles: add/remove from extraWorkingDays to make it ON (Working).
            const isWorking = prev.extraWorkingDays.includes(date);
            if (isWorking) {
                // Remove from extraWorkingDays -> Reverts to Weekend (Holiday)
                return { ...prev, extraWorkingDays: prev.extraWorkingDays.filter(d => d !== date) };
            } else {
                // Add to extraWorkingDays -> Becomes Working Day
                return { ...prev, extraWorkingDays: [...prev.extraWorkingDays, date] };
            }
        } else {
            // Logic for Weekdays:
            // Default: ON (Working).
            // If user toggles: add/remove from holidays to make it OFF (Holiday).
            const isHoliday = prev.holidays.includes(date);
            if (isHoliday) {
                // Remove from holidays -> Reverts to Weekday (Working)
                return { ...prev, holidays: prev.holidays.filter(d => d !== date) };
            } else {
                // Add to holidays -> Becomes Holiday
                return { ...prev, holidays: [...prev.holidays, date] };
            }
        }
    });
  };

  // Generate projection data for the chart
  const projectionData = useMemo(() => {
    const data = [];
    const currentAttended = Math.max(0, state.totalClasses - state.absentClasses);
    const startPct = state.totalClasses === 0 ? 0 : (currentAttended / state.totalClasses) * 100;

    data.push({
      name: 'Today',
      attendAll: parseFloat(startPct.toFixed(1)),
      bunkAll: parseFloat(startPct.toFixed(1)),
    });

    for (let i = 1; i <= 7; i++) {
        const added = i * 6; // 6 classes/day
        const newTotal = state.totalClasses + added;

        const attendedIfAll = currentAttended + added;
        const attendedIfNone = currentAttended;

        data.push({
            name: `Day +${i}`,
            attendAll: parseFloat(((attendedIfAll / newTotal) * 100).toFixed(1)),
            bunkAll: parseFloat(((attendedIfNone / newTotal) * 100).toFixed(1)),
        });
    }
    return data;
  }, [state.totalClasses, state.absentClasses]);

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { staggerChildren: 0.1 } }
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: { y: 0, opacity: 1 }
  };

  const attendedCount = Math.max(0, state.totalClasses - state.absentClasses);
  const attendanceInputValue = inputMode === 'absent' ? state.absentClasses : attendedCount;

  // Calculate total days off count (Holidays + Weekends - Extra Working Days) for UI display?
  // Just showing selected holidays count + working weekends count might be confusing.
  // Let's just show explicit overrides count or simplified message.
  const customHolidaysCount = state.holidays.length;

  return (
    <div className="min-h-screen py-10 px-4 md:py-20 md:px-12 max-w-7xl mx-auto">
      <motion.div
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="grid grid-cols-1 lg:grid-cols-2 gap-6 lg:gap-12"
      >
        {/* Controls Section */}
        <motion.div variants={itemVariants} className="space-y-6 md:space-y-8">
          <div className="glass-panel p-5 md:p-8 rounded-3xl neon-glow relative overflow-hidden group">
            <div className="absolute top-0 right-0 w-32 h-32 bg-cyan-500/10 rounded-full blur-3xl transform translate-x-16 -translate-y-16 group-hover:bg-cyan-500/20 transition-all duration-500"></div>

            <h2 className="text-2xl md:text-3xl font-bold mb-6 md:mb-8 text-white">Input Data</h2>

            <div className="space-y-5 md:space-y-6">
              {/* Total Classes */}
              <div className="space-y-2">
                <label className="text-slate-400 text-xs md:text-sm uppercase tracking-wider font-semibold">Total Classes Held</label>
                <input
                  type="number"
                  min="0"
                  value={state.totalClasses || ''}
                  onChange={(e) => handleChange('totalClasses', parseInt(e.target.value) || 0)}
                  className="w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-3 md:py-4 text-white focus:outline-none focus:border-cyan-500 transition-colors text-base md:text-lg"
                  placeholder="e.g. 120"
                />
              </div>

              {/* Attendance Input (Absent or Present) */}
              <div className="space-y-2">
                <div className="flex justify-between items-center">
                    <label className="text-slate-400 text-xs md:text-sm uppercase tracking-wider font-semibold">
                        {inputMode === 'absent' ? 'Classes Absent' : 'Classes Attended'}
                    </label>

                    <div className="bg-slate-900 p-1 rounded-lg flex text-[10px] md:text-xs font-medium">
                        <button
                            onClick={() => setInputMode('absent')}
                            className={`px-3 py-1 rounded-md transition-all ${inputMode === 'absent' ? 'bg-red-500/20 text-red-300 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                        >
                            Absent
                        </button>
                        <button
                            onClick={() => setInputMode('present')}
                            className={`px-3 py-1 rounded-md transition-all ${inputMode === 'present' ? 'bg-cyan-500/20 text-cyan-300 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                        >
                            Present
                        </button>
                    </div>
                </div>

                <input
                  type="number"
                  min="0"
                  max={state.totalClasses}
                  value={attendanceInputValue || ''}
                  onChange={(e) => handleAttendanceChange(parseInt(e.target.value) || 0)}
                  className={`w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-3 md:py-4 text-white focus:outline-none transition-colors text-base md:text-lg ${inputMode === 'absent' ? 'focus:border-red-500/50' : 'focus:border-cyan-500/50'}`}
                  placeholder={inputMode === 'absent' ? "e.g. 15" : "e.g. 105"}
                />
              </div>

              {/* Exam Date */}
              <div className="space-y-2">
                <label className="text-slate-400 text-xs md:text-sm uppercase tracking-wider font-semibold">Exam Start Date</label>
                <input
                  type="date"
                  value={state.examDate}
                  onChange={(e) => handleChange('examDate', e.target.value)}
                  className="w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-3 md:py-4 text-white focus:outline-none focus:border-cyan-500 transition-colors text-base md:text-lg [color-scheme:dark]"
                />
              </div>

               {/* Holidays */}
               <div className="space-y-2">
                  <div className="flex justify-between items-center mb-2">
                    <label className="text-slate-400 text-xs md:text-sm uppercase tracking-wider font-semibold">Calendar</label>
                    <span className="text-[10px] md:text-xs text-slate-500">Select holidays & deselect weekends</span>
                  </div>

                  <button 
