import React, { useState } from 'react';
import { motion } from 'framer-motion';

interface CalendarProps {
  holidays: string[];
  extraWorkingDays: string[];
  onDateToggle: (date: string, isWeekend: boolean) => void;
}

export const Calendar: React.FC<CalendarProps> = ({ holidays, extraWorkingDays, onDateToggle }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  const getDaysInMonth = (year: number, month: number) => {
    return new Date(year, month + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (year: number, month: number) => {
    return new Date(year, month, 1).getDay();
  };

  const formatDate = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const daysInMonth = getDaysInMonth(year, month);
  const firstDay = getFirstDayOfMonth(year, month);

  const days = [];
  // Empty slots for prev month
  for (let i = 0; i < firstDay; i++) {
    days.push(null);
  }
  // Days
  for (let i = 1; i <= daysInMonth; i++) {
    days.push(new Date(year, month, i));
  }

  const handlePrevMonth = () => {
    setCurrentDate(new Date(year, month - 1, 1));
  };

  const handleNextMonth = () => {
    setCurrentDate(new Date(year, month + 1, 1));
  };

  const isWeekend = (date: Date) => {
    const day = date.getDay();
    return day === 0 || day === 6;
  };

  const isToday = (date: Date) => {
    const today = new Date();
    return date.getDate() === today.getDate() && 
           date.getMonth() === today.getMonth() && 
           date.getFullYear() === today.getFullYear();
  };

  return (
    <div className="w-full select-none max-w-sm mx-auto">
      <div className="flex justify-between items-center mb-2">
        <button 
            onClick={handlePrevMonth} 
            className="p-1.5 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white transition-colors active:scale-95"
        >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" />
            </svg>
        </button>
        <h3 className="text-white font-bold text-sm font-mono">
            {currentDate.toLocaleDateString('default', { month: 'long', year: 'numeric' })}
        </h3>
        <button 
            onClick={handleNextMonth} 
            className="p-1.5 hover:bg-slate-800 rounded-lg text-slate-400 hover:text-white transition-colors active:scale-95"
        >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M7.293 14.707a1 1 0 010-1.414L10.586 10 7.293 6.707a1 1 0 011.414-1.414l4 4a1 1 0 010 1.414l-4 4a1 1 0 01-1.414 0z" clipRule="evenodd" />
            </svg>
        </button>
      </div>

      <div className="grid grid-cols-7 gap-1 mb-1">
        {['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'].map(day => (
            <div key={day} className="text-center text-[10px] text-slate-500 uppercase font-bold py-1">
                {day}
            </div>
        ))}
      </div>

      <div className="grid grid-cols-7 gap-1">
        {days.map((date, index) => {
            if (!date) return <div key={`empty-${index}`} />;

            const weekend = isWeekend(date);
            const dateStr = formatDate(date);
            const today = isToday(date);

            // A day is visually "selected" (Cyan/Holiday) if it is a day OFF.
            // 1. Weekend: OFF by default, unless in extraWorkingDays
            // 2. Weekday: ON by default, unless in holidays
            const isOff = weekend ? !extraWorkingDays.includes(dateStr) : holidays.includes(dateStr);

            return (
                <motion.button
                    key={dateStr}
                    whileTap={{ scale: 0.9 }}
                    onClick={() => onDateToggle(dateStr, weekend)}
                    className={`
                        aspect-square rounded-md flex flex-col items-center justify-center text-xs relative transition-colors duration-200 touch-manipulation
                        ${isOff ? 'bg-cyan-600/80 text-white shadow-[0_0_10px_rgba(8,145,178,0.4)]' : 
                          'bg-slate-800/40 text-slate-400 hover:bg-slate-700 hover:text-slate-200'}
                        ${today ? 'ring-1 ring-cyan-500/50' : ''}
                    `}
                >
                    <span className="relative z-10">{date.getDate()}</span>
                    {isOff && (
                        <motion.div 
                            layoutId={`selected-${dateStr}`} // Unique layout ID prevents cross-animation issues
                            className="absolute inset-0 border border-cyan-400/50 rounded-md" 
                            initial={false}
                        />
                    )}
                    {today && !isOff && (
                         <div className="absolute bottom-1 w-1 h-1 bg-cyan-400 rounded-full" />
                    )}
                </motion.button>
            );
        })}
      </div>

      <div className="mt-2 flex flex-col sm:flex-row gap-2 text-[10px] text-slate-500 justify-center">
        <div className="flex items-center gap-2 bg-slate-800/50 p-1.5 rounded-lg justify-center">
            <div className="w-2.5 h-2.5 bg-cyan-600/80 rounded shadow-[0_0_5px_rgba(8,145,178,0.5)] flex-shrink-0"></div>
            <span>Holiday</span>
        </div>
        <div className="flex items-center gap-2 bg-slate-800/50 p-1.5 rounded-lg justify-center">
            <div className="w-2.5 h-2.5 bg-slate-800/40 border border-slate-700 rounded flex-shrink-0"></div>
            <span>Working</span>
        </div>
      </div>
    </div>
  );
};

