import React, { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence, useSpring } from 'framer-motion';
import { AttendanceState, AttendanceStats } from '../types';
import { calculateStats } from '../utils/calculations';
import { Modal } from './Modal';
import { Calendar } from './Calendar';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';

// Helper component for smooth number transitions
const AnimatedCounter: React.FC<{ value: number; className?: string; toFixed?: number }> = ({ value, className, toFixed = 0 }) => {
  const ref = useRef<HTMLSpanElement>(null);
  const springValue = useSpring(value, { stiffness: 60, damping: 20 });

  useEffect(() => {
    springValue.set(value);
  }, [value, springValue]);

  useEffect(() => {
    return springValue.on("change", (latest) => {
      if (ref.current) {
        ref.current.textContent = latest.toFixed(toFixed);
      }
    });
  }, [springValue, toFixed]);

  return <span ref={ref} className={className}>{value.toFixed(toFixed)}</span>;
};

export const Dashboard: React.FC = () => {
  const [state, setState] = useState<AttendanceState>({
    totalClasses: 0,
    absentClasses: 0,
    examDate: '',
    holidays: [],
    extraWorkingDays: []
  });

  const [stats, setStats] = useState<AttendanceStats | null>(null);
  const [isHolidayModalOpen, setIsHolidayModalOpen] = useState(false);
  const [inputMode, setInputMode] = useState<'absent' | 'present'>('absent');

  useEffect(() => {
    setStats(calculateStats(state));
  }, [state]);

  const handleChange = (field: keyof AttendanceState, value: any) => {
    setState(prev => {
        const newState = { ...prev, [field]: value };

        if (field === 'totalClasses') {
            const newTotal = Math.max(0, Number(value));
            newState.totalClasses = newTotal;
            // Absent cannot be more than total
            if (newState.absentClasses > newTotal) {
                newState.absentClasses = newTotal;
            }
        } else if (field === 'absentClasses') {
            const newAbsent = Math.max(0, Number(value));
            // Absent cannot be more than total
            if (newAbsent > newState.totalClasses) {
                newState.absentClasses = newState.totalClasses;
            } else {
                newState.absentClasses = newAbsent;
            }
        }

        return newState;
    });
  };

  const handleAttendanceChange = (val: number) => {
    if (inputMode === 'absent') {
      handleChange('absentClasses', val);
    } else {
      // User is inputting "Present" classes
      const currentTotal = state.totalClasses;
      const validPresent = Math.min(Math.max(0, val), currentTotal);
      const newAbsent = currentTotal - validPresent;
      handleChange('absentClasses', newAbsent);
    }
  };

  const toggleHoliday = (date: string, isWeekend: boolean) => {
    setState(prev => {
        if (isWeekend) {
            // Logic for Weekends:
            // Default: OFF (Holiday).
            // If user toggles: add/remove from extraWorkingDays to make it ON (Working).
            const isWorking = prev.extraWorkingDays.includes(date);
            if (isWorking) {
                // Remove from extraWorkingDays -> Reverts to Weekend (Holiday)
                return { ...prev, extraWorkingDays: prev.extraWorkingDays.filter(d => d !== date) };
            } else {
                // Add to extraWorkingDays -> Becomes Working Day
                return { ...prev, extraWorkingDays: [...prev.extraWorkingDays, date] };
            }
        } else {
            // Logic for Weekdays:
            // Default: ON (Working).
            // If user toggles: add/remove from holidays to make it OFF (Holiday).
            const isHoliday = prev.holidays.includes(date);
            if (isHoliday) {
                // Remove from holidays -> Reverts to Weekday (Working)
                return { ...prev, holidays: prev.holidays.filter(d => d !== date) };
            } else {
                // Add to holidays -> Becomes Holiday
                return { ...prev, holidays: [...prev.holidays, date] };
            }
        }
    });
  };

  // Generate projection data for the chart
  const projectionData = useMemo(() => {
    const data = [];
    const currentAttended = Math.max(0, state.totalClasses - state.absentClasses);
    const startPct = state.totalClasses === 0 ? 0 : (currentAttended / state.totalClasses) * 100;

    data.push({
      name: 'Today',
      attendAll: parseFloat(startPct.toFixed(1)),
      bunkAll: parseFloat(startPct.toFixed(1)),
    });

    for (let i = 1; i <= 7; i++) {
        const added = i * 6; // 6 classes/day
        const newTotal = state.totalClasses + added;

        const attendedIfAll = currentAttended + added;
        const attendedIfNone = currentAttended;

        data.push({
            name: `Day +${i}`,
            attendAll: parseFloat(((attendedIfAll / newTotal) * 100).toFixed(1)),
            bunkAll: parseFloat(((attendedIfNone / newTotal) * 100).toFixed(1)),
        });
    }
    return data;
  }, [state.totalClasses, state.absentClasses]);

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { staggerChildren: 0.1 } }
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: { y: 0, opacity: 1 }
  };

  const attendedCount = Math.max(0, state.totalClasses - state.absentClasses);
  const attendanceInputValue = inputMode === 'absent' ? state.absentClasses : attendedCount;

  const customHolidaysCount = state.holidays.length;

  return (
    <div className="min-h-screen py-10 px-4 md:py-20 md:px-12 max-w-7xl mx-auto">
      <motion.div
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="grid grid-cols-1 lg:grid-cols-2 gap-6 lg:gap-12"
      >
        {/* Controls Section */}
        <motion.div variants={itemVariants} className="space-y-6 md:space-y-8">
          <div className="glass-panel p-4 md:p-6 rounded-3xl neon-glow relative overflow-hidden group">
            <div className="absolute top-0 right-0 w-32 h-32 bg-cyan-500/10 rounded-full blur-3xl transform translate-x-16 -translate-y-16 group-hover:bg-cyan-500/20 transition-all duration-500"></div>

            <h2 className="text-2xl md:text-3xl font-bold mb-4 md:mb-6 text-white">Input Data</h2>

            <div className="space-y-4 md:space-y-5">
              {/* Total Classes */}
              <div className="space-y-1.5">
                <label className="text-slate-400 text-xs md:text-sm uppercase tracking-wider font-semibold">Total Classes Held</label>
                <input
                  type="number"
                  min="0"
                  value={state.totalClasses || ''}
                  onChange={(e) => handleChange('totalClasses', parseInt(e.target.value) || 0)}
                  className="w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-2.5 md:py-3 text-white focus:outline-none focus:border-cyan-500 transition-colors text-base md:text-lg"
                  placeholder="e.g. 120"
                />
              </div>

              {/* Attendance Input (Absent or Present) */}
              <div className="space-y-1.5">
                <div className="flex justify-between items-center">
                    <label className="text-slate-400 text-xs md:text-sm uppercase tracking-wider font-semibold">
                        {inputMode === 'absent' ? 'Classes Absent' : 'Classes Attended'}
                    </label>

                    <div className="bg-slate-900 p-1 rounded-lg flex text-[10px] md:text-xs font-medium">
                        <button
                            onClick={() => setInputMode('absent')}
                            className={`px-3 py-1 rounded-md transition-all ${inputMode === 'absent' ? 'bg-red-500/20 text-red-300 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                        >
                            Absent
                        </button>
                        <button
                            onClick={() => setInputMode('present')}
                            className={`px-3 py-1 rounded-md transition-all ${inputMode === 'present' ? 'bg-cyan-500/20 text-cyan-300 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}
                        >
                            Present
                        </button>
                    </div>
                </div>

                <input
                  type="number"
                  min="0"
                  max={state.totalClasses}
                  value={attendanceInputValue || ''}
                  onChange={(e) => handleAttendanceChange(parseInt(e.target.value) || 0)}
                  className={`w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-2.5 md:py-3 text-white focus:outline-none transition-colors text-base md:text-lg ${inputMode === 'absent' ? 'focus:border-red-500/50' : 'focus:border-cyan-500/50'}`}
                  placeholder={inputMode === 'absent' ? "e.g. 15" : "e.g. 105"}
                />
              </div>

              {/* Exam Date */}
              <div className="space-y-1.5">
                <label className="text-slate-400 text-xs md:text-sm uppercase tracking-wider font-semibold">Exam Start Date</label>
                <input
                  type="date"
                  value={state.examDate}
                  onChange={(e) => handleChange('examDate', e.target.value)}
                  className="w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-2.5 md:py-3 text-white focus:outline-none focus:border-cyan-500 transition-colors text-base md:text-lg [color-scheme:dark]"
                />
              </div>

               {/* Holidays */}
               <div className="space-y-1.5">
                  <div className="flex justify-between items-center mb-1">
                    <label className="text-slate-400 text-xs md:text-sm uppercase tracking-wider font-semibold">Calendar</label>
                    <span className="text-[10px] md:text-xs text-slate-500">Select holidays & deselect weekends</span>
                  </div>

                  <button 
                    onClick={() => setIsHolidayModalOpen(true)}
                    className="w-full bg-slate-900/50 border border-slate-700 hover:border-cyan-500/50 hover:bg-slate-800/50 rounded-xl px-4 py-2.5 md:py-3 text-left flex justify-between items-center group transition-all"
                  >
                     <span className="text-slate-300 text-sm md:text-base truncate mr-2">
                        {customHolidaysCount === 0 && state.extraWorkingDays.length === 0 
                            ? "Configure Calendar" 
                            : `${customHolidaysCount} Holidays, ${state.extraWorkingDays.length} Wknd Classes`}
                     </span>
                     <span className="text-cyan-500 bg-cyan-500/10 p-1.5 rounded-lg group-hover:bg-cyan-500/20 transition-colors flex-shrink-0">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                        </svg>
                     </span>
                  </button>

                  {(state.holidays.length > 0 || state.extraWorkingDays.length > 0) && (
                      <div className="flex flex-wrap gap-2 mt-2">
                          {state.holidays.slice(0, 3).map(h => (
                              <span key={h} className="bg-cyan-900/30 border border-cyan-700/50 text-cyan-200 text-[10px] md:text-xs px-2 py-1 rounded-md">
                                  {h} (Hol)
                              </span>
                          ))}
                          {state.extraWorkingDays.slice(0, 3).map(h => (
                              <span key={h} className="bg-slate-700/50 border border-slate-600 text-slate-300 text-[10px] md:text-xs px-2 py-1 rounded-md">
                                  {h} (Work)
                              </span>
                          ))}
                          {(state.holidays.length + state.extraWorkingDays.length) > 5 && (
                              <span className="bg-slate-800 border border-slate-700 text-slate-400 text-[10px] md:text-xs px-2 py-1 rounded-md">
                                  +{state.holidays.length + state.extraWorkingDays.length - 5} more
                              </span>
                          )}
                      </div>
                  )}
               </div>
            </div>
          </div>
        </motion.div>

        {/* Analytics Section */}
        <motion.div variants={itemVariants} className="space-y-6">

          {/* Main Percentage Card */}
          <div className="glass-panel p-6 md:p-8 rounded-3xl relative overflow-hidden flex flex-col items-center justify-center text-center h-full min-h-[320px] md:min-h-[400px]">
            <motion.div 
              className={`absolute -inset-16 rounded-full blur-3xl opacity-50 transition-colors duration-1000 ${stats?.isSafe ? 'bg-cyan-900' : 'bg-red-900'}`}
              animate={{ scale: [1, 1.1, 1], rotate: [0, 90, 0] }}
              transition={{ duration: 20, repeat: Infinity, ease: 'easeInOut' }}
            />

            <h3 className="text-slate-400 font-medium mb-4 uppercase tracking-widest text-xs md:text-sm z-10">Current Attendance</h3>
            <div className="relative z-10 mb-4">
                <svg className="w-48 h-48 md:w-64 md:h-64 transform -rotate-90" viewBox="0 0 256 256">
                    <defs>
                      <filter id="glow-cyan" x="-50%" y="-50%" width="200%" height="200%">
                        <feDropShadow dx="0" dy="0" stdDeviation="4.5" floodColor="#22d3ee" />
                      </filter>
                      <filter id="glow-red" x="-50%" y="-50%" width="200%" height="200%">
                        <feDropShadow dx="0" dy="0" stdDeviation="4.5" floodColor="#f87171" />
                      </filter>
                    </defs>
                    <circle cx="128" cy="128" r="120" stroke="#1e293b" strokeWidth="12" fill="transparent" />
                    <circle cx="128" cy="128" r="100" stroke="#1e293b" strokeWidth="1" fill="transparent" strokeDasharray="2 8" />

                    {/* Background Pulse Circle */}
                    {stats?.isSafe && (
                        <motion.circle 
                            cx="128" cy="128" r="120" 
                            stroke="#22d3ee" 
                            strokeWidth="2"
                            fill="transparent"
                            initial={{ opacity: 0.5, scale: 1 }}
                            animate={{ opacity: 0, scale: 1.1 }}
                            transition={{ duration: 2, repeat: Infinity, ease: "easeOut" }}
                            style={{ transformOrigin: "128px 128px" }}
                        />
                    )}

                    <motion.circle 
                        cx="128" cy="128" r="120" 
                        stroke={stats?.isSafe ? "#22d3ee" : "#f87171"} 
                        strokeWidth="12" 
                        fill="transparent"
                        strokeDasharray={2 * Math.PI * 120}
                        strokeLinecap="round"
                        initial={{ strokeDashoffset: 2 * Math.PI * 120 }}
                        animate={{ strokeDashoffset: 2 * Math.PI * 120 * (1 - (stats?.currentPercentage || 0) / 100) }}
                        transition={{ duration: 1.5, type: "spring", stiffness: 50, damping: 15 }}
                        style={{ filter: `url(#glow-${stats?.isSafe ? 'cyan' : 'red'})` }}
                    />
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span className="text-5xl md:text-7xl font-bold text-white tracking-tighter bg-clip-text text-transparent bg-gradient-to-b from-white to-slate-400 drop-shadow-lg tabular-nums">
                        <AnimatedCounter value={stats?.currentPercentage || 0} toFixed={1} />%
                    </span>

                    <AnimatePresence mode="wait">
                      <motion.span
                        key={stats?.isSafe ? 'safe' : 'danger'}
                        initial={{ opacity: 0, scale: 0.8 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.8 }}
                        transition={{ duration: 0.3 }}
                        className={`mt-1 md:mt-2 px-3 py-1 md:px-4 md:py-1.5 rounded-full text-[10px] md:text-xs font-bold uppercase tracking-wider ${stats?.isSafe ? 'bg-cyan-500/20 text-cyan-300' : 'bg-red-500/20 text-red-300'} border ${stats?.isSafe ? 'border-cyan-500/30' : 'border-red-500/30'}`}
                      >
                          {stats?.isSafe ? 'Safe Zone' : 'Danger Zone'}
                      </motion.span>
                    </AnimatePresence>
                </div>
            </div>

            {/* Attendance Breakdown */}
            <div className="relative z-10 flex gap-6 text-xs md:text-sm font-medium">
                <div className="flex items-center gap-2">
                    <div className="w-2 h-2 rounded-full bg-cyan-400 shadow-[0_0_8px_rgba(34,211,238,0.5)]"></div>
                    <span className="text-slate-300">Present: <span className="text-white"><AnimatedCounter value={attendedCount} /></span></span>
                </div>
                <div className="flex items-center gap-2">
                    <div className="w-2 h-2 rounded-full bg-red-400 shadow-[0_0_8px_rgba(248,113,113,0.5)]"></div>
                    <span className="text-slate-300">Absent: <span className="text-white"><AnimatedCounter value={state.absentClasses} /></span></span>
                </div>
            </div>
          </div>
        </motion.div>

        {/* Stats Grid - Full Width */}
        <motion.div variants={itemVariants} className="col-span-1 lg:col-span-2 grid grid-cols-1 md:grid-cols-3 gap-4 md:gap-6">

            {/* Safe to Bunk Card */}
            <div className="glass-panel p-5 md:p-6 rounded-2xl relative overflow-hidden group min-h-[140px] md:min-h-[160px] flex flex-col justify-center">
                <div className="absolute inset-0 bg-gradient-to-br from-green-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                <h4 className="text-slate-400 text-[10px] md:text-sm font-bold uppercase tracking-wider mb-2 md:mb-3">BUNKABLE POTENTIAL</h4>

                {stats?.hasExamDate ? (
                  <>
                    <div className="flex items-end gap-2">
                        <span className="text-4xl md:text-5xl font-bold text-white tabular-nums">
                            <AnimatedCounter value={stats?.bunkableClasses || 0} />
                        </span>
                        <span className="text-xs md:text-sm text-slate-500 mb-1 pb-1">classes</span>
                    </div>
                    <p className="text-xs md:text-sm text-slate-400 mt-2 font-medium">
                        Equivalent to <span className="text-cyan-400 font-bold"><AnimatedCounter value={stats?.bunkableDays || 0} /> full days</span> of absence while staying safe.
                    </p>
                  </>
                ) : (
                  <p className="text-xs md:text-sm text-slate-500 italic mt-2 leading-relaxed">
                    Select a future exam date to calculate bunkability.
                  </p>
                )}
            </div>

            {/* Recovery Card (MUST ATTEND) */}
            <div className="glass-panel p-5 md:p-6 rounded-2xl relative overflow-hidden group min-h-[140px] md:min-h-[160px] flex flex-col justify-center">
                <div className="absolute inset-0 bg-gradient-to-br from-purple-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                <h4 className="text-slate-400 text-[10px] md:text-sm font-bold uppercase tracking-wider mb-2 md:mb-3">
                  {stats?.hasExamDate ? (stats?.isPossibleToReachTarget ? 'MUST ATTEND' : 'TARGET UNREACHABLE') : 'MUST ATTEND'}
                </h4>

                {!stats?.hasExamDate ? (
                  <>
                    <div className="flex items-end gap-2">
                        <span className="text-4xl md:text-5xl font-bold text-white tabular-nums">
                            <AnimatedCounter value={stats?.requiredClasses || 0} />
                        </span>
                        <span className="text-xs md:text-sm text-slate-500 mb-1 pb-1">classes</span>
                    </div>
                    <p className="text-xs md:text-sm text-slate-400 mt-2 font-medium">
                        Classes needed <span className="text-purple-400 font-bold">immediately</span> to reach 75%. (Exam date needed for long-term check)
                    </p>
                  </>
                ) : stats?.isPossibleToReachTarget ? (
                  <>
                    <div className="flex items-end gap-2">
                        <span className="text-4xl md:text-5xl font-bold text-white tabular-nums">
                            <AnimatedCounter value={stats?.requiredClasses || 0} />
                        </span>
                        <span className="text-xs md:text-sm text-slate-500 mb-1 pb-1">classes</span>
                    </div>
                    <p className="text-xs md:text-sm text-slate-400 mt-2 font-medium">
                        You need <span className="text-cyan-400 font-bold"><AnimatedCounter value={stats?.requiredDays || 0} /> full days</span> of attendance to reach 75%.
                    </p>
                  </>
                ) : (
                  <>
                    <div className="flex items-end gap-2">
                        <span className="text-4xl md:text-5xl font-bold text-red-400 tabular-nums">
                            <AnimatedCounter value={stats?.maxAchievablePercentage || 0} toFixed={1} />%
                        </span>
                        <span className="text-xs md:text-sm text-slate-500 mb-1 pb-1">max</span>
                    </div>
                    <p className="text-xs md:text-sm text-red-400 mt-2 font-medium">
                        Even with 100% attendance from now, you cannot hit 75% before the exam.
                    </p>
                  </>
                )}
            </div>

            {/* Tomorrow Projection */}
            <div className="glass-panel p-5 md:p-6 rounded-2xl relative overflow-hidden group min-h-[140px] md:min-h-[160px] flex flex-col justify-center">
                 <div className="absolute inset-0 bg-gradient-to-br from-orange-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                <h4 className="text-slate-400 text-[10px] md:text-sm font-bold uppercase tracking-wider mb-2 md:mb-3">IF ABSENT TOMORROW</h4>
                <div className="flex items-end gap-2">
                    <span className={`text-4xl md:text-5xl font-bold tabular-nums ${(stats?.tomorrowImpact || 0) < 75 ? 'text-red-400' : 'text-orange-300'}`}>
                        <AnimatedCounter value={stats?.tomorrowImpact || 0} toFixed={1} />%
                    </span>
                </div>
                <p className="text-xs md:text-sm text-slate-400 mt-2">
                    Your percentage drops to this if you miss all 6 classes tomorrow.
                </p>
            </div>
        </motion.div>

        {/* Projection Chart Section */}
        <motion.div variants={itemVariants} className="col-span-1 lg:col-span-2">
            <div className="glass-panel p-6 md:p-8 rounded-3xl relative overflow-hidden">
                <h3 className="text-slate-400 font-medium mb-6 uppercase tracking-widest text-xs md:text-sm">7-Day Attendance Projection</h3>
                <div className="h-[300px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <AreaChart data={projectionData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                            <defs>
                                <linearGradient id="colorCyan" x1="0" y1="0" x2="0" y2="1">
                                    <stop offset="5%" stopColor="#22d3ee" stopOpacity={0.3}/>
                                    <stop offset="95%" stopColor="#22d3ee" stopOpacity={0}/>
                                </linearGradient>
                                <linearGradient id="colorRed" x1="0" y1="0" x2="0" y2="1">
                                    <stop offset="5%" stopColor="#f87171" stopOpacity={0.3}/>
                                    <stop offset="95%" stopColor="#f87171" stopOpacity={0}/>
                                </linearGradient>
                            </defs>
                            <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                            <XAxis 
                                dataKey="name" 
                                stroke="#64748b" 
                                fontSize={12} 
                                tickLine={false} 
                                axisLine={false}
                                tickMargin={10} 
                            />
                            <YAxis 
                                stroke="#64748b" 
                                fontSize={12} 
                                tickLine={false} 
                                axisLine={false} 
                                domain={[0, 100]}
                                tickFormatter={(value) => `${value}%`}
                            />
                            <Tooltip 
                                contentStyle={{ backgroundColor: '#0f172a', borderColor: '#334155', borderRadius: '12px', color: '#f8fafc' }}
                                itemStyle={{ fontSize: '12px' }}
                                labelStyle={{ color: '#94a3b8', marginBottom: '8px' }}
                            />
                            <ReferenceLine y={75} stroke="#94a3b8" strokeDasharray="3 3" label={{ position: 'right', value: '75%', fill: '#94a3b8', fontSize: 10 }} />
                            <Area 
                                type="monotone" 
                                dataKey="attendAll" 
                                name="If Attending All"
                                stroke="#22d3ee" 
                                fillOpacity={1} 
                                fill="url(#colorCyan)" 
                                strokeWidth={2}
                            />
                            <Area 
                                type="monotone" 
                                dataKey="bunkAll" 
                                name="If Bunking All"
                                stroke="#f87171" 
                                fillOpacity={1} 
                                fill="url(#colorRed)" 
                                strokeWidth={2}
                            />
                        </AreaChart>
                    </ResponsiveContainer>
                </div>
                <div className="mt-4 flex flex-col md:flex-row gap-2 md:gap-6 justify-center text-xs text-slate-400">
                    <div className="flex items-center gap-2">
                        <span className="w-3 h-3 rounded-full bg-cyan-500/20 border border-cyan-500"></span>
                        <span>Projection if Attending All Classes</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <span className="w-3 h-3 rounded-full bg-red-500/20 border border-red-500"></span>
                        <span>Projection if Bunking All Classes</span>
                    </div>
                </div>
            </div>
        </motion.div>

      </motion.div>

      <Modal 
        isOpen={isHolidayModalOpen} 
        onClose={() => setIsHolidayModalOpen(false)}
        title="Select Holidays & Working Days"
      >
        <Calendar 
            holidays={state.holidays}
            extraWorkingDays={state.extraWorkingDays}
            onDateToggle={toggleHoliday} 
        />
      </Modal>
    </div>
  );
};
